@icontract.snapshot(lambda context_tar: context_tar['archive'], name='archive')
@icontract.ensure(lambda context_tar, archive: all(item in archive for item in context_tar['archive']), "All archive items are processed")
@icontract.ensure(lambda context_tar: all('out' in item and 'in' in item for item in context_tar['archive']), "All archive items have 'in' and 'out'")
@icontract.ensure(lambda context_tar: all(isinstance(item['in'], str) and isinstance(item['out'], str) for item in context_tar['archive']), "'in' and 'out' are strings")
def tar_archive(context_tar):
    logger.debug("start")

    mode = get_file_mode_for_writing(context_tar)

    for item in context_tar['archive']:
        destination = item['out']
        source = item['in']
        with tarfile.open(destination, mode) as archive_me:
            logger.debug("Archiving '%s' to '%s'", source, destination)

            archive_me.add(source, arcname='.')
            logger.info("Archived '%s' to '%s'", source, destination)

    logger.debug("end")

